const staticData = $getWorkflowStaticData('global');
const runId = $node['Normalize + Validate Input'].json.runId;
const run = staticData.runs?.[runId];
if (!run) return [];

run.step = 'extract';
run.progress = Math.max(run.progress, 63);
run.logs.push({t:new Date().toISOString(), m:`Preparing docs for extraction. Total: ${(run.docs||[]).length}`});

function score(d){
  let s = 0;
  const u = (d.url||'').toLowerCase();
  const t = (d.text_preview||'').toLowerCase();
  const kw = ['licit','contrat','compra','adjud','proveedor','presup','ejecuc','auditor','boletin','ordenanza','resoluc','decreto','subsid','obra'];
  for (const k of kw) if (u.includes(k) || t.includes(k)) s += 2;
  if (u.includes('gob.ar')) s += 3;
  // PDFs with URL source are high priority for extraction
  if (d.kind === 'pdf' && d.pdfUrl) s += 5;
  if (d.has_text) s += 1;
  if (d.error) s -= 3;
  return s;
}

const docs = (run.docs||[]).filter(d => d.has_text && !d.error);
docs.sort((a,b)=>score(b)-score(a));

const maxDocs = run.isPremium ? 30 : 12;
const pick = docs.slice(0, maxDocs);

run.logs.push({t:new Date().toISOString(), m:`Selected ${pick.length}/${docs.length} docs for LLM (${pick.filter(d=>d.pdfUrl).length} PDFs via URL)` });

if (pick.length === 0) {
  run.logs.push({t:new Date().toISOString(), m:'No extractable docs, generating signals from metadata only'});
  run.extracted = run.extracted || { documents:[], fragments:[], actors:[], procedures:[], relations:[] };
  return [{ json: { runId, localityName: run.localityName, _noDocsToExtract: true } }];
}

return pick.map(d => ({
  runId,
  url: d.url,
  kind: d.kind,
  text: d.text_preview || '',
  pdfUrl: d.pdfUrl || null
}));
